const { chromium } = require('playwright');
const path = require('path');

(async () => {
    const browser = await chromium.launch({ executablePath: process.env.PLAYWRIGHT_CHROMIUM_EXECUTABLE_PATH || undefined });
    const page = await browser.newPage();
    await page.setViewportSize({ width: 1920, height: 1080 });

    const htmlPath = path.resolve('/app/presentation.html');
    const http = require('http');
    const fs = require('fs');
    const handler = require('http');

    // Start simple server
    const server = http.createServer((req, res) => {
        let filePath = '/app' + req.url;
        if (filePath === '/app/') filePath = '/app/presentation.html';
        try {
            const data = fs.readFileSync(filePath);
            const ext = path.extname(filePath);
            const types = {'.html':'text/html','.jpg':'image/jpeg','.png':'image/png','.css':'text/css','.js':'text/javascript'};
            res.writeHead(200, {'Content-Type': types[ext] || 'application/octet-stream'});
            res.end(data);
        } catch(e) {
            res.writeHead(404);
            res.end('Not found');
        }
    });

    await new Promise(resolve => server.listen(9876, resolve));
    await page.goto('http://127.0.0.1:9876/presentation.html', { waitUntil: 'networkidle' });
    await page.waitForTimeout(1000);

    const slideCount = await page.$$eval('.slide', els => els.length);
    console.log('Found ' + slideCount + ' slides');

    const outDir = '/app/slide_captures';
    fs.mkdirSync(outDir, { recursive: true });

    for (let i = 0; i < slideCount; i++) {
        await page.evaluate((idx) => {
            const slides = document.querySelectorAll('.slide');
            slides[idx].scrollIntoView({ behavior: 'instant' });
            slides[idx].classList.add('visible');
        }, i);
        await page.waitForTimeout(400);
        const idx = String(i + 1).padStart(3, '0');
        await page.screenshot({ path: `${outDir}/slide_${idx}.png` });
        console.log('Captured slide ' + (i + 1));
    }

    server.close();
    await browser.close();
    console.log(JSON.stringify({ captured: slideCount }));
})();
